import { buildContext, createForEachItemProxy } from "../shared/context.js";
import { FOR_EACH_PLACEHOLDER } from "./build.js";
export function forEach(_ctx, config) {
    const item = createForEachItemProxy(FOR_EACH_PLACEHOLDER);
    const innerCtx = buildContext([]);
    return {
        key: "forEach",
        config: { forEach: config.collection },
        operatorChildren: [{ label: null, tasks: config.actions(item, innerCtx) }],
    };
}
export function switchAction(_ctx, config) {
    if (config.cases.length === 0)
        throw new Error("switch requires at least one case");
    const innerCtx = buildContext([]);
    const operatorChildren = config.cases.map((c) => ({
        label: c.label,
        ...(c.condition !== undefined ? { filter: c.condition } : {}),
        tasks: c.actions(innerCtx),
    }));
    if (config.defaultActions) {
        const isPlainFn = typeof config.defaultActions === "function";
        const actionsFn = isPlainFn ? config.defaultActions : config.defaultActions.actions;
        const defaultLabel = isPlainFn ? undefined : config.defaultActions.label;
        const defaultFilterMode = isPlainFn ? undefined : config.defaultActions.defaultFilterMode;
        operatorChildren.push({
            label: null,
            isDefault: true,
            ...(defaultLabel !== undefined ? { defaultLabel } : {}),
            ...(defaultFilterMode !== undefined ? { defaultFilterMode } : {}),
            tasks: actionsFn(innerCtx),
        });
    }
    return { key: "switch", config: {}, operatorChildren };
}
export function forkJoin(_ctx, config) {
    const innerCtx = buildContext([]);
    return {
        key: "forkJoin",
        config: {},
        operatorChildren: config.branches.map((b) => ({ label: b.label, tasks: b.actions(innerCtx) })),
    };
}
